package com.ds.goroute.service.impl;
import com.ds.goroute.constant.ErrorConstant;import com.ds.goroute.dto.request.*;import com.ds.goroute.dto.response.*;import com.ds.goroute.entity.*;import com.ds.goroute.exception.BusinessException;import com.ds.goroute.repository.*;import com.ds.goroute.service.*;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import lombok.RequiredArgsConstructor;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service @RequiredArgsConstructor
public class MarketplaceChatServiceImpl implements MarketplaceChatService {
 private final MarketplaceChatRepository repo;private final HotelMarketplaceRepository hotelRepo;private final ActivityCommerceRepository activityRepo;private final HostOrganizationRepository orgRepo;private final UserRepository userRepo;private final PartnerAuthorizationService authorization;private final MarketplaceHistoryService history;private final WebSocketService webSocketService;private final ObjectMapper mapper;
 @Transactional public MarketplaceConversationResponse start(UUID actor,StartMarketplaceConversationRequest r){String type=r.getConversationType();if(type==null)throw bad("conversationType is required");if("HOTEL_BOOKING".equals(type))return startHotel(actor,r.getHotelBookingId());if("ACTIVITY_ORDER".equals(type))return startActivity(actor,r.getActivityOrderId());if(!"DIRECT".equals(type))throw bad("Invalid conversation type");List<UUID> users=new ArrayList<>(r.getParticipantUserIds()==null?List.of():r.getParticipantUserIds());users.removeIf(Objects::isNull);if(users.stream().noneMatch(actor::equals))users.add(actor);users=users.stream().distinct().toList();if(users.size()<2||users.size()>20)throw bad("Direct conversation requires 2-20 participants");for(UUID u:users)userRepo.findById(u).orElseThrow(()->new BusinessException(ErrorConstant.USER_NOT_FOUND));MarketplaceConversation c=create("DIRECT",null,null,null);for(UUID u:users)repo.addMember(c.getId(),u,u.equals(actor)?"CREATOR":"PARTICIPANT",c.getCreatedAt());history.record(null,"CONVERSATION",c.getId(),"CREATED",c,List.of(),actor,"USER",null);return response(c);}
 private MarketplaceConversationResponse startHotel(UUID actor,UUID id){if(id==null)throw bad("hotelBookingId is required");MarketplaceConversation existing=repo.findByHotelBooking(id,actor).orElse(null);if(existing!=null){require(existing.getId(),actor);return response(existing);}HotelBooking b=hotelRepo.findBooking(id).orElseThrow(()->notFound("Hotel booking not found"));if(!actor.equals(b.getUserId()))authorization.requireResourcePermission(b.getOrganizationId(),actor,"HOTEL",b.getHotelId(),"CHAT_WRITE");MarketplaceConversation c=create("HOTEL_BOOKING",b.getOrganizationId(),b.getId(),null);if(b.getUserId()!=null)repo.addMember(c.getId(),b.getUserId(),"GUEST",c.getCreatedAt());if(!actor.equals(b.getUserId()))repo.addMember(c.getId(),actor,"HOST",c.getCreatedAt());history.record(b.getOrganizationId(),"CONVERSATION",c.getId(),"CREATED",c,List.of(),actor,"USER",null);return response(repo.find(c.getId(),actor).orElse(c));}
 private MarketplaceConversationResponse startActivity(UUID actor,UUID id){if(id==null)throw bad("activityOrderId is required");MarketplaceConversation existing=repo.findByActivityOrder(id,actor).orElse(null);if(existing!=null){require(existing.getId(),actor);return response(existing);}ActivityOrder o=activityRepo.findOrder(id).orElseThrow(()->notFound("Activity order not found"));if(!actor.equals(o.getUserId()))authorization.requireResourcePermission(o.getOrganizationId(),actor,"ACTIVITY",o.getActivityBookingId(),"CHAT_WRITE");MarketplaceConversation c=create("ACTIVITY_ORDER",o.getOrganizationId(),null,o.getId());if(o.getUserId()!=null)repo.addMember(c.getId(),o.getUserId(),"GUEST",c.getCreatedAt());if(!actor.equals(o.getUserId()))repo.addMember(c.getId(),actor,"HOST",c.getCreatedAt());history.record(o.getOrganizationId(),"CONVERSATION",c.getId(),"CREATED",c,List.of(),actor,"USER",null);return response(repo.find(c.getId(),actor).orElse(c));}
 private MarketplaceConversation create(String type,UUID org,UUID booking,UUID order){LocalDateTime n=LocalDateTime.now();MarketplaceConversation c=MarketplaceConversation.builder().id(UUID.randomUUID()).conversationType(type).organizationId(org).hotelBookingId(booking).activityOrderId(order).status("OPEN").createdAt(n).updatedAt(n).build();try{repo.insertConversation(c);}catch(DataIntegrityViolationException ex){MarketplaceConversation found=booking!=null?repo.findByHotelBooking(booking,null).orElse(null):repo.findByActivityOrder(order,null).orElse(null);if(found!=null)return found;throw ex;}return c;}
 public List<MarketplaceConversationResponse> listMine(UUID a,int p,int s){Page r=page(p,s);return repo.findForUser(a,r.l,r.o).stream().map(this::response).toList();}
 public MarketplaceConversationResponse get(UUID a,UUID id){require(id,a);return response(conversation(id,a));}
 public List<MarketplaceMessageResponse> messages(UUID a,UUID id,Long after,int limit){require(id,a);return rawMessages(id,after,limit);}
 @Transactional public MarketplaceMessageResponse send(UUID a,UUID id,SendMarketplaceMessageRequest r){require(id,a);ensureConversationMember(id,a);if("SYSTEM".equals(r.getMessageType()))throw forbidden();if((r.getContent()==null||r.getContent().isBlank())&&(r.getAttachments()==null||r.getAttachments().isEmpty()))throw bad("Message content or attachment is required");MarketplaceMessage prior=repo.findMessageByClientId(id,a,r.getClientMessageId()).orElse(null);if(prior!=null)return messageResponse(prior);repo.lock(id);prior=repo.findMessageByClientId(id,a,r.getClientMessageId()).orElse(null);if(prior!=null)return messageResponse(prior);LocalDateTime n=LocalDateTime.now();MarketplaceMessage m=MarketplaceMessage.builder().id(UUID.randomUUID()).conversationId(id).senderUserId(a).clientMessageId(r.getClientMessageId()).messageType(r.getMessageType()==null?"TEXT":r.getMessageType()).content(r.getContent()==null?null:r.getContent().trim()).attachments(json(r.getAttachments()==null?List.of():r.getAttachments())).sequenceNo(repo.nextSequence(id)).createdAt(n).build();repo.insertMessage(m);repo.updateLast(id,n);MarketplaceMessageResponse saved=messageResponse(repo.findMessage(m.getId()).orElse(m));broadcastAfterCommit(id,a,saved);return saved;}
 @Transactional public void markRead(UUID a,UUID id,UUID messageId){require(id,a);ensureConversationMember(id,a);MarketplaceMessage m=repo.findMessage(messageId).orElseThrow(()->notFound("Message not found"));if(!id.equals(m.getConversationId()))throw bad("Message does not belong to conversation");repo.markRead(id,a,messageId);}
 public List<MarketplaceConversationResponse> partnerList(UUID a,UUID org,String status,int p,int s){authorization.requireOrganization(org,a);Page r=page(p,s);return repo.findForOrganization(org,a,clean(status),r.l,r.o).stream().filter(c->canPartnerAccess(c,a)).map(this::response).toList();}
 @Transactional public MarketplaceConversationResponse partnerUpdate(UUID a,UUID id,UpdateConversationStatusRequest r){MarketplaceConversation c=conversation(id,a);if(c.getOrganizationId()==null)throw bad("Direct conversation cannot be assigned by partner");require(id,a);if(r.getAssignedMemberId()!=null){OrganizationMember member=orgRepo.findMembers(c.getOrganizationId()).stream().filter(m->r.getAssignedMemberId().equals(m.getId())&&"ACTIVE".equals(m.getMemberStatus())).findFirst().orElseThrow(()->bad("Assigned employee is not active in this organization"));if(!canPartnerAccess(c,member.getUserId()))throw bad("Assigned employee does not have access to this conversation resource");}repo.updateConversation(id,r.getStatus(),r.getAssignedMemberId(),LocalDateTime.now());MarketplaceConversation saved=conversation(id,a);history.record(saved.getOrganizationId(),"CONVERSATION",id,"UPDATED",saved,List.of("status","assignedMemberId"),a,"USER",null);return response(saved);}
 public List<MarketplaceConversationResponse> adminList(String q,String status,int p,int s){Page r=page(p,s);return repo.findAdmin(clean(q),clean(status),r.l,r.o).stream().map(this::response).toList();}
 public List<MarketplaceMessageResponse> adminMessages(UUID id,Long after,int limit){conversation(id,null);return rawMessages(id,after,limit);}
 @Transactional public MarketplaceConversationResponse adminUpdate(UUID actor,UUID id,UpdateConversationStatusRequest r){MarketplaceConversation c=conversation(id,null);if(r.getAssignedMemberId()!=null){if(c.getOrganizationId()==null)throw bad("Direct conversation cannot be assigned");orgRepo.findMembers(c.getOrganizationId()).stream().filter(m->r.getAssignedMemberId().equals(m.getId())&&"ACTIVE".equals(m.getMemberStatus())).findFirst().orElseThrow(()->bad("Assigned employee is not active in this organization"));}repo.updateConversation(id,r.getStatus(),r.getAssignedMemberId(),LocalDateTime.now());MarketplaceConversation saved=conversation(id,null);history.record(saved.getOrganizationId(),"CONVERSATION",id,"ADMIN_UPDATED",saved,List.of("status","assignedMemberId"),actor,"ADMIN",null);return response(saved);}
 @Transactional public MarketplaceMessageResponse adminSend(UUID actor,UUID id,SendMarketplaceMessageRequest r){MarketplaceConversation c=conversation(id,null);if(c.getOrganizationId()==null)throw bad("Admin cannot join a private direct conversation");return send(actor,id,r);}
 @Transactional public void adminRedact(UUID actor,UUID conversationId,UUID messageId,String reason){MarketplaceConversation c=conversation(conversationId,null);MarketplaceMessage m=repo.findMessage(messageId).orElseThrow(()->notFound("Message not found"));if(!conversationId.equals(m.getConversationId()))throw bad("Message does not belong to conversation");if(repo.softDeleteMessage(conversationId,messageId,LocalDateTime.now())!=1)throw bad("Message is already deleted");history.record(c.getOrganizationId(),"CONVERSATION_MESSAGE",messageId,"ADMIN_REDACTED",m,List.of("content","attachments"),actor,"ADMIN",clean(reason));}
 private List<MarketplaceMessageResponse> rawMessages(UUID id,Long after,int limit){int l=Math.min(Math.max(limit,1),200);return repo.findMessages(id,after,l).stream().map(this::messageResponse).toList();}
 private void require(UUID id,UUID a){MarketplaceConversation c=conversation(id,a);if(c.getOrganizationId()==null){if(!repo.canAccess(id,a))throw forbidden();return;}if(c.getHotelBookingId()!=null){HotelBooking b=hotelRepo.findBooking(c.getHotelBookingId()).orElseThrow(()->notFound("Hotel booking not found"));if(a.equals(b.getUserId()))return;authorization.requireResourcePermission(c.getOrganizationId(),a,"HOTEL",b.getHotelId(),"CHAT_WRITE");return;}if(c.getActivityOrderId()!=null){ActivityOrder o=activityRepo.findOrder(c.getActivityOrderId()).orElseThrow(()->notFound("Activity order not found"));if(a.equals(o.getUserId()))return;authorization.requireResourcePermission(c.getOrganizationId(),a,"ACTIVITY",o.getActivityBookingId(),"CHAT_WRITE");return;}authorization.requirePermission(c.getOrganizationId(),a,"CHAT_WRITE");}private void ensureConversationMember(UUID id,UUID userId){MarketplaceConversation c=conversation(id,userId);if(c.getOrganizationId()==null)return;String role="HOST";if(c.getHotelBookingId()!=null){HotelBooking b=hotelRepo.findBooking(c.getHotelBookingId()).orElseThrow(()->notFound("Hotel booking not found"));if(userId.equals(b.getUserId()))role="GUEST";}else if(c.getActivityOrderId()!=null){ActivityOrder o=activityRepo.findOrder(c.getActivityOrderId()).orElseThrow(()->notFound("Activity order not found"));if(userId.equals(o.getUserId()))role="GUEST";}repo.addMember(id,userId,role,LocalDateTime.now());}private boolean canPartnerAccess(MarketplaceConversation c,UUID a){if(c.getHotelBookingId()!=null){HotelBooking b=hotelRepo.findBooking(c.getHotelBookingId()).orElse(null);return b!=null&&authorization.hasResourcePermission(c.getOrganizationId(),a,"HOTEL",b.getHotelId(),"CHAT_WRITE");}if(c.getActivityOrderId()!=null){ActivityOrder o=activityRepo.findOrder(c.getActivityOrderId()).orElse(null);return o!=null&&authorization.hasResourcePermission(c.getOrganizationId(),a,"ACTIVITY",o.getActivityBookingId(),"CHAT_WRITE");}return true;}private MarketplaceConversation conversation(UUID id,UUID v){return repo.find(id,v).orElseThrow(()->notFound("Conversation not found"));}
 private MarketplaceConversationResponse response(MarketplaceConversation c){return MarketplaceConversationResponse.builder().id(c.getId()).conversationType(c.getConversationType()).organizationId(c.getOrganizationId()).hotelBookingId(c.getHotelBookingId()).activityOrderId(c.getActivityOrderId()).status(c.getStatus()).assignedMemberId(c.getAssignedMemberId()).organizationName(c.getOrganizationName()).bookingCode(c.getBookingCode()).orderCode(c.getOrderCode()).lastMessageContent(c.getLastMessageContent()).unreadCount(c.getUnreadCount()).lastMessageAt(c.getLastMessageAt()).createdAt(c.getCreatedAt()).updatedAt(c.getUpdatedAt()).build();}
 private MarketplaceMessageResponse messageResponse(MarketplaceMessage m){return MarketplaceMessageResponse.builder().id(m.getId()).conversationId(m.getConversationId()).senderUserId(m.getSenderUserId()).senderName(m.getSenderName()).senderAvatarUrl(m.getSenderAvatarUrl()).clientMessageId(m.getClientMessageId()).messageType(m.getMessageType()).content(m.getDeletedAt()==null?m.getContent():null).attachments(m.getDeletedAt()==null?readAttachments(m.getAttachments()):List.of()).sequenceNo(m.getSequenceNo()).editedAt(m.getEditedAt()).deletedAt(m.getDeletedAt()).createdAt(m.getCreatedAt()).build();}
 private void broadcastAfterCommit(UUID conversationId,UUID actor,MarketplaceMessageResponse response){Map<String,Object> data=mapper.convertValue(response,new TypeReference<Map<String,Object>>(){});if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive()){org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){webSocketService.broadcastToConversation(conversationId,"MESSAGE_CREATED",data,actor);}});}else webSocketService.broadcastToConversation(conversationId,"MESSAGE_CREATED",data,actor);}private String json(Object v){try{return mapper.writeValueAsString(v);}catch(JsonProcessingException e){throw new BusinessException(ErrorConstant.INTERNAL_SERVER_ERROR,"Cannot serialize chat data");}}private List<Map<String,Object>> readAttachments(String s){if(s==null)return List.of();try{return mapper.readValue(s,new TypeReference<List<Map<String,Object>>>(){});}catch(Exception e){return List.of();}}private Page page(int p,int s){int l=Math.min(Math.max(s,1),200);return new Page(l,Math.max(p,0)*l);}private String clean(String s){return s==null||s.isBlank()?null:s.trim();}private BusinessException bad(String m){return new BusinessException(ErrorConstant.BAD_REQUEST,m);}private BusinessException notFound(String m){return new BusinessException(ErrorConstant.NOT_FOUND,m);}private BusinessException forbidden(){return new BusinessException(ErrorConstant.FORBIDDEN_ERROR,"You cannot access this conversation");}private record Page(int l,int o){}
}
